package dev.zomboid.hordes;
import java.util.*;import fixture.*;import fixture.Game.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.network.chat.Component;import dev.zomboid.remains.CorpseBridge35;
public class CorpseChecks35{
 static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}static ItemStack s(String id,int n){return new ItemStack(new Item(id),n);}static List<Object>live(Corpse c){return new ArrayList<>(c.inventory.content.stream().filter(o->!((ItemStack)o).isEmpty()).toList());}
 public static class Type{String id;Type(String s){id=s;}public String getDescriptionId(){return "entity."+id;}}
 public static class Enemy extends Actor{public String type="minecraft.zombie";public String name;public Object getType(){return new Type(type);}public Component getCustomName(){return name==null?null:Component.literal(name);}public Object position(){return new Object();}}
 public static class Inv{public List<Object>content=new ArrayList<>();public Inv(int n){ensure(n);}public void ensure(int n){while(content.size()<n)content.add(ItemStack.EMPTY);}public int getContainerSize(){return content.size();}public Object getItem(int n){return content.get(n);}public void setItem(int n,Object s){content.set(n,s);}public void clearContent(){Collections.fill(content,ItemStack.EMPTY);}public void setChanged(){}}
 public static class Corpse{public Inv inventory;public int quality;public boolean mutant;public List<Object>generated=new ArrayList<>();public Corpse(int n){inventory=new Inv(n);generated.add(s("minecraft:bread",20));generated.add(s("minecraft:leather_leggings",1));generated.add(s("minecraft:iron_pickaxe",4));generated.add(s("minecraft:diamond",9));}}
 public record Event(Enemy getEntity){}public record Drop(Object getItem){}
 static Corpse run(Enemy e,int q){Corpse c=new Corpse(27);c.quality=q;CorpseBridge35.body(c,e.world,new Event(e));return c;}
 static boolean contains(List<?>list,ItemStack expected){for(Object o:list){ItemStack a=(ItemStack)o;if(ItemStack.isSameItemSameComponents(a,expected)&&a.count==expected.count&&a.ammo==expected.ammo&&a.damage==expected.damage)return true;}return false;}
 public static void main(String[]a)throws Exception{
  BuiltInRegistries.ITEM.item("firstaid:bandage");for(String id:List.of("minecraft:rotten_flesh","minecraft:bone","minecraft:slime_ball","minecraft:spider_eye","minecraft:string","minecraft:iron_sword"))BuiltInRegistries.ITEM.item(id);BuiltInRegistries.ITEM.data.put("fracturepoint:military_helmet",new ArmorItem("fracturepoint:military_helmet"));
  var defaults=WorldTuning.snapshot();ok(Math.abs(defaults.get("loot_arma_rara")-100./13)<.00001,"weapon default one in thirteen");ok(defaults.get("loot_municion_rara")==35,"matching ammunition default thirty five");Map<String,Double>draft=new HashMap<>(defaults);draft.put("ia_oido",.7);draft.put("bandidos_armados",6.);CorpseBalance35.prepare(draft);ok(draft.get("ia_oido")==.7&&draft.get("bandidos_armados")==6,"targeted migration preserves AI and NPC preferences");
  int weapons=0,clothes=0,firearms=0,ammo=0;Enemy civilian=new Enemy();civilian.world.random=new Random(350013);
  for(int q=0;q<6;q++){int tierWeapons=0;for(int sample=0;sample<1300;sample++){Corpse c=run(civilian,q);int wc=0,ac=0,bc=0;ItemStack foundGun=null,foundAmmo=null;for(Object o:live(c)){ItemStack stack=(ItemStack)o;int k=LootNerf.kind(stack);if(k==LootNerf.WEAPON){wc++;weapons++;tierWeapons++;if(stack.getItem()instanceof GunItem){firearms++;foundGun=stack;ok(stack.ammo==0&&!stack.barrel,"no hidden loaded ammunition roll");}}if(k==LootNerf.ARMOR){ac++;clothes++;}if(k==LootNerf.AMMO){bc++;ammo++;foundAmmo=stack;}}ok(wc<=1&&ac<=1&&bc<=1,"one generated weapon armor and ammo category");ok(foundAmmo==null||foundGun!=null,"no unrelated ammunition");if(foundAmmo!=null)ok(foundAmmo.ammoId.equals(foundGun.ammoId)&&foundAmmo.count>=2&&foundAmmo.count<=9,"matching caliber and bounded pile");}
  ok(tierWeapons>65&&tierWeapons<140,"every quality uses roughly one in thirteen not stacked chance");}
  ok(weapons>500&&weapons<700,"weapon rate over 7800 bodies");ok(clothes>500&&clothes<700,"military clothing rate over 7800 bodies");ok((double)ammo/firearms>.28&&(double)ammo/firearms<.42,"conditional ammunition near thirty five percent");
  Enemy soldier=new Enemy();soldier.name="Military Juggernaut";ItemStack gun=new ItemStack(new GunItem(),1);gun.ammo=37;gun.component="owned attachments";gun.damage=80;ItemStack helmet=new ItemStack(new ArmorItem("fracturepoint:juggernaut_helmet"),1);helmet.component="battery and armor data";ItemStack off=s("minecraft:shield",1);soldier.setItemSlot(EquipmentSlot.HEAD,helmet);soldier.setItemSlot(EquipmentSlot.MAINHAND,gun);soldier.setItemSlot(EquipmentSlot.OFFHAND,off);
  Class<?>subscriber=Class.forName("dev.zomboid.remains.EquipmentCapture35");ok(subscriber.getAnnotation(net.neoforged.fml.common.EventBusSubscriber.class).modid().equals("zombie_remains_loot"),"automatic death subscriber uses correct mod id");var death=subscriber.getMethod("death",net.neoforged.neoforge.event.entity.living.LivingDeathEvent.class);ok(death.isAnnotationPresent(net.neoforged.bus.api.SubscribeEvent.class),"death handler registered with game event bus");death.invoke(null,new net.neoforged.neoforge.event.entity.living.LivingDeathEvent(soldier));for(EquipmentSlot slot:EquipmentSlot.values())soldier.setItemSlot(slot,ItemStack.EMPTY);Collection<Drop>drops=new ArrayList<>(List.of(new Drop(gun.copy()),new Drop(helmet.copy()),new Drop(s("minecraft:iron_sword",1))));CorpseBridge35.clear(drops,new Event(soldier));ok(drops.isEmpty(),"original native drop clear semantics retained");Corpse military=run(soldier,0);List<Object>loot=live(military);ok(contains(loot,gun)&&contains(loot,helmet)&&contains(loot,off),"all real military equipment preserved without rarity roll");ok(loot.stream().filter(o->ItemStack.isSameItemSameComponents((ItemStack)o,gun)).count()==1,"equipment/drop overlap does not duplicate gun");ok(loot.stream().anyMatch(o->((ItemStack)o).getItem().id.equals("firstaid:bandage")&&((ItemStack)o).count==2),"military bandages guaranteed");ok(loot.stream().anyMatch(o->((ItemStack)o).getItem().id.equals("minecraft:iron_sword")),"real event gear retained after native clear");
  Enemy bandit=new Enemy();bandit.type="tacznpcs.npc";bandit.tag.putString("TacZNpcJob","military");Corpse full=new Corpse(27);List<ItemStack>cargo=new ArrayList<>();for(int i=0;i<27;i++){ItemStack item=s("minecraft:diamond",i+1);item.component="cargo "+i;cargo.add(item);full.inventory.setItem(i,item);}CorpseBridge35.body(full,bandit.world,new Event(bandit));ok(full.inventory.getContainerSize()>=28,"full NPC cargo expands for military bandage");for(ItemStack item:cargo)ok(contains(live(full),item),"every real NPC cargo entry retained");
  for(String type:List.of("crawler","blister_zombie","split_head_zombie","rotten_mutant","spitter","zombie_brute","mutant_brute")){Enemy mutant=new Enemy();mutant.type="mutantszombies."+type;Corpse body=new Corpse(54);body.mutant=true;CorpseBridge35.body(body,mutant.world,new Event(mutant));for(Object o:live(body)){String id=((ItemStack)o).getItem().id;ok(Set.of("minecraft:rotten_flesh","minecraft:bone","minecraft:slime_ball","minecraft:spider_eye","minecraft:string").contains(id),"mutant biological loot instead of food/coins/clothes");}ok(!live(body).isEmpty(),"mutant has natural remains");}
  Enemy e=new Enemy();ItemStack sword=s("minecraft:iron_sword",1);sword.component="owned melee";e.setItemSlot(EquipmentSlot.MAINHAND,sword);CorpseBridge35.capture(new Event(e));e.setItemSlot(EquipmentSlot.MAINHAND,ItemStack.EMPTY);ok(contains(live(run(e,0)),sword),"civilian actual held item also preserved");
  Corpse decoded=new Corpse(27);decoded.inventory.setItem(0,s("minecraft:bread",2));decoded.inventory.setItem(1,s("minecraft:bone",3));CorpseBridge35.scatter(decoded,civilian.world);ok(live(decoded).size()==2,"post-decode NPC scatter preserves cargo");ok(((ItemStack)decoded.inventory.getItem(0)).isEmpty()||((ItemStack)decoded.inventory.getItem(1)).isEmpty(),"NPC scatter survives native compact serialization");
  Set<String>arrangements=new HashSet<>();for(int i=0;i<20;i++){Corpse b=run(civilian,0);List<Integer>slots=new ArrayList<>();for(int j=0;j<27;j++)if(!((ItemStack)b.inventory.getItem(j)).isEmpty())slots.add(j);arrangements.add(slots.toString());}ok(arrangements.size()>15,"inventory placement randomized including empty slots");ok(CorpseBalance35.GEAR.isEmpty()&&CorpseBalance35.DROPS.isEmpty(),"death snapshots released after processing");
  @SuppressWarnings("unchecked") Map<String,Double>settings=(Map<String,Double>)ZoneReflection.get(WorldTuning.class,"values");double saved=settings.get("loot_arma_rara");settings.put("loot_arma_rara",100.);Object swordItem=BuiltInRegistries.ITEM.data.remove("minecraft:iron_sword");BuiltInRegistries.ITEM.item("minecraft:iron_axe");Enemy axeEnemy=new Enemy();axeEnemy.world.random=new Random(){public double nextDouble(){return .9;}};List<Object>axeLoot=live(run(axeEnemy,2));ok(axeLoot.stream().anyMatch(o->((ItemStack)o).item.id.equals("minecraft:iron_axe")),"rolled melee axe survives one-tool cap");ok(axeLoot.stream().filter(CorpseProfessions::tool).count()==1,"axe replaces generated pickaxe instead of losing successful weapon roll");settings.put("loot_arma_rara",saved);BuiltInRegistries.ITEM.data.remove("minecraft:iron_axe");BuiltInRegistries.ITEM.data.put("minecraft:iron_sword",swordItem);
  System.out.println("CORPSE_CHECKS="+checks);System.out.println("SAMPLES=7800 weapons="+weapons+" military_clothes="+clothes+" firearms="+firearms+" paired_ammo="+ammo);
 }
}
